<?php require dirname(__DIR__).'/app/bootstrap.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{foreach(['dhaka','outside'] as $area){$v=trim((string)($_POST[$area]??''));if($v!==''&&(!ctype_digit($v)||(int)$v>100000))throw new DomainException('Delivery fees must be blank or a whole BDT amount.');}foreach(['dhaka','outside'] as $area)query('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',['delivery_'.$area,trim($_POST[$area])?:($_POST[$area]==='0'?'0':null)]);flash('Delivery fees saved. Existing order totals are unchanged.');redirect('admin/settings.php');}catch(DomainException $e){$error=$e->getMessage();}}render_header('Store settings',true); ?>
<main class="page narrow"><p class="eyebrow">STORE SETTINGS</p><h1>The essentials.</h1><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif ?><form method="post"><?=csrf_input()?><h2>Delivery fees</h2><p>Set your actual delivery charges. Leave blank to confirm the amount with each customer. Enter 0 only if delivery is free.</p><label>Inside Dhaka (BDT)<input type="number" name="dhaka" min="0" max="100000" value="<?=h(setting('delivery_dhaka'))?>"></label><label>Outside Dhaka (BDT)<input type="number" name="outside" min="0" max="100000" value="<?=h(setting('delivery_outside'))?>"></label><button class="button dark">SAVE SETTINGS ↗</button></form><h2 class="spaced">Google Sheets & email</h2><p>Automatically log new orders and notify urbanwearflawed@gmail.com and customers.</p><a class="button outline" href="<?=url('admin/notifications.php')?>">CONNECT GOOGLE & EMAIL ↗</a><h2 class="spaced">bKash</h2><p>Not connected. The payment adapter is reserved in app/payments.php. Merchant credentials and a tested create/execute/query flow are required before enabling online payment. Never collect PINs or OTPs here.</p></main><?php render_footer(); ?>
